import * as T from './vendor/three.module.js';
export function installBridge({scene,camera,colliders,pause,rewards,getCurrentSeat=()=>null,getNearbyPlaces=()=>[]}){
 const root=new T.Group();root.name='Krown Bridge and west-bank lookout';scene.add(root);
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.85}),wood=mat('#886344'),trim=mat('#d0b68c'),green=mat('#58734c'),stone=mat('#b7ac95'),gold=mat('#d6b264');
 const part=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=part(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.2,d:d/2+.2});return o;};
 box(-57,-.18,153,10,.4,50,green);box(-57,.07,153,3,.12,45,stone);box(-57,.08,168,7,.12,8,stone);
 box(-50,.15,172.5,18,.22,3,wood);for(let i=0;i<36;i++)box(-58.75+i*.5,.268,172.5,.025,.012,3,trim);
 for(const z of [171,174]){box(-49,1.15,z,8,.16,.15,trim,true);for(let i=0;i<9;i++){const x=-53+i;box(x,.65,z,.12,1.25,.12,wood,true);part(new T.OctahedronGeometry(.13),gold,x,1.42,z);}}
 for(const x of [-53,-45])for(const z of [171,174])box(x,.5,z,.3,1.4,.3,wood);
 box(-58,.6,163,.8,.2,2.8,wood,true);box(-58.35,1.05,163,.12,.9,2.8,wood);const seats=[{name:'Krown Bridge river lookout bench',x:-58,z:163,y:1.5,yaw:-Math.PI/2,approach:{x:-56.5,z:163},kind:'bridge'}];
 box(-57,1.2,166.5,3,2,.18,wood,true);
 function sign(text,x,y,z,w,h){const c=document.createElement('canvas');c.width=Math.round(w*160);c.height=Math.round(h*160);const ctx=c.getContext('2d');ctx.fillStyle='#315a4a';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff0c8';ctx.textAlign='center';ctx.textBaseline='middle';let size=c.height*.5;ctx.font=size+'px Georgia';size*=Math.min(1,c.width*.92/ctx.measureText(text).width);ctx.font=size+'px Georgia';ctx.fillText(text,c.width/2,c.height/2);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;part(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),x,y,z);}
 sign('KROWN BRIDGE',-57,2,166.62,2.8,.5);
 sign('Community idea · @ed033',-57,1.4,166.63,2.8,.35);
 const boardPoint={x:-57,z:168,name:'Krown Bridge story and west-bank lookout'};const near=()=>Math.hypot(camera.position.x-boardPoint.x,camera.position.z-boardPoint.z)<1.5;
 const canRead=()=>near()||seats.includes(getCurrentSeat());
 const dialog=document.createElement('dialog');dialog.id='bridgeMenu';dialog.setAttribute('aria-labelledby','bridgeTitle');const title=document.createElement('h2');title.id='bridgeTitle';title.textContent='Krown Bridge';const intro=document.createElement('p');intro.textContent='Krown Bridge was contributed by @ed033 to the original Krownlandia places list. Its Riverbend location, timber design and lookout are new prototype interpretations; the source does not specify a location or design.';const story=document.createElement('p');story.id='bridgeStory';story.setAttribute('role','status');const status=document.createElement('p');status.id='bridgeStatus';const actions=document.createElement('div');const topics=[['story','Read the bridge story','A bridge joins two riverbanks and gives visitors a new view of the village. This crossing connects Riverbend’s path to a quiet west-bank lookout, inspired by @ed033’s Krown Bridge idea.']];for(const [id,label,text]of topics){const b=document.createElement('button');b.id='bridgeTopic-'+id;b.textContent=label;b.onclick=()=>{if(!canRead()||!dialog.open)return;story.textContent=text;rewards.completeBridge();refresh();};actions.append(b);}const reward=document.createElement('button');reward.id='bridgeRewards';reward.textContent='Find bridge rewards';reward.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideTo('bridge');dialog.close();};const close=document.createElement('button');close.id='bridgeClose';close.textContent='Return to the bridge';close.onclick=()=>dialog.close();dialog.append(title,intro,actions,story,status,reward,close);document.body.append(dialog);const css=document.createElement('link');css.rel='stylesheet';css.href='bridge.css';document.head.append(css);
 const nearby=document.createElement('details');nearby.id='bridgeNearby';const nearbyTitle=document.createElement('summary');nearbyTitle.textContent='Explore nearby';const nearbyList=document.createElement('div');nearby.append(nearbyTitle,nearbyList);
 function refreshNearby(){nearby.open=false;nearbyList.replaceChildren();for(const point of getNearbyPlaces()){const button=document.createElement('button');button.id='bridgeWalk-'+point.id;button.textContent='Walk to '+point.name;button.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideToPoint({x:point.x,z:point.z,name:point.name});dialog.close();};nearbyList.append(button);}nearby.hidden=nearbyList.children.length===0;}
 dialog.append(nearby);
 function refresh(){const st=rewards.state();status.textContent=st.claims.includes('bridge:task')?'Your bridge discovery reward is collected.':st.done.includes('bridge-board')?'Story explored · 20 task points are ready at the bridge rewards station.':'Read the bridge story to unlock 20 task points.';if(!st.saved)status.textContent+=' Progress lasts for this visit only.';}
 return {seats,boardPoint,get near(){return near()},get isOpen(){return dialog.open},open(){if(!canRead()||dialog.open)return false;pause();story.textContent='Read about the community idea behind Krown Bridge.';refresh();refreshNearby();dialog.showModal();return true;}};
}
